public interface BookJpaRepository extends JpaRepository<BookJpaEntity, UUID> {

    List<BookJpaEntity> findByTitleContainingIgnoreCaseOrderByTitleAsc(String title);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
