    public Optional<Book> loadBookForUpdate(UUID bookId) {
        return bookJpaRepository.findByIdForUpdate(bookId).map(bookMapper::toDomain);
    }

    @Override
    public List<Book> loadBooksByTitle(String title) {
        return bookJpaRepository.findByTitleContainingIgnoreCaseOrderByTitleAsc(title).stream()
                .map(bookMapper::toDomain)
                .toList();
    }

    @Override
