import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.Optional;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select l from LoanJpaEntity l where l.id = :loanId")
    Optional<LoanJpaEntity> findByIdForUpdate(@Param("loanId") UUID loanId);

    @Query(value = "select new com.example.lending.adapter.out.persistence.ActiveLoanRow(l.id, l.bookId, b.title, l.loanedAt, l.dueAt) "
            + "from LoanJpaEntity l left join BookJpaEntity b on b.id = l.bookId "
            + "where l.memberId = :memberId and l.returnedAt is null "
            + "order by l.loanedAt, l.id",
            countQuery = "select count(l) from LoanJpaEntity l where l.memberId = :memberId and l.returnedAt is null")
    Page<ActiveLoanRow> findActiveLoanRowsByMemberId(@Param("memberId") UUID memberId, Pageable pageable);
}
