@SpringBootTest
@AutoConfigureMockMvc
class LoanLimitApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void a_member_can_hold_up_to_five_loans_and_the_sixth_is_rejected_with_409() throws Exception {
        String memberId = registerMember("이준호");

        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanBody(registerBook(), memberId)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void sponsor_member_can_borrow_beyond_five_loans() throws Exception {
        String sponsorId = "11111111-1111-1111-1111-111111111111";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + sponsorId + "\",\"name\":\"후원자\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(sponsorId));

        for (int i = 0; i < 6; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanBody(registerBook(), sponsorId)))
                    .andExpect(status().isCreated());
        }
    }

    @Test
    void loaning_with_an_unregistered_member_id_returns_404() throws Exception {
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(registerBook(), UUID.randomUUID().toString())))
                .andExpect(status().isNotFound());
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Effective Java\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    record LoanBody(String bookId, String memberId) {
    }
}

