package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409() throws Exception {
        String bookId = registerBook();

        mockMvc.perform(reserve(bookId, registerMember("권나은")))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_discarded_book_returns_409() throws Exception {
        String bookId = registerBook();
        mockMvc.perform(post("/books/{bookId}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(reserve(bookId, registerMember("권나은")))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_an_unknown_book_or_member_returns_404() throws Exception {
        String bookId = registerBook();
        String memberId = registerMember("권나은");
        loanBook(bookId, registerMember("윤서진"));

        mockMvc.perform(reserve(UUID.randomUUID().toString(), memberId))
                .andExpect(status().isNotFound());
        mockMvc.perform(reserve(bookId, UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    @Test
    void reservations_on_a_loaned_book_are_queued_in_order() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember("윤서진"));

        String first = registerMember("강도윤");
        String second = registerMember("임하린");
        String firstReservationId = reserveAndGetId(bookId, first, 1);
        String secondReservationId = reserveAndGetId(bookId, second, 2);

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].reservationId").value(firstReservationId))
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].reservationId").value(secondReservationId))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void the_same_member_cannot_reserve_the_same_book_twice() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember("윤서진"));
        String memberId = registerMember("강도윤");
        reserveAndGetId(bookId, memberId, 1);

        mockMvc.perform(reserve(bookId, memberId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void after_return_only_the_head_of_the_queue_can_loan() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember("윤서진"));
        String head = registerMember("강도윤");
        String next = registerMember("임하린");
        reserveAndGetId(bookId, head, 1);
        reserveAndGetId(bookId, next, 2);

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(loan(bookId, next))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));

        mockMvc.perform(loan(bookId, head))
                .andExpect(status().isCreated());

        // 맨 앞 예약자가 빌리면 예약은 소진되고 다음 사람이 맨 앞이 된다.
        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(next))
                .andExpect(jsonPath("$[0].position").value(1));
    }

    @Test
    void a_book_without_reservations_can_be_loaned_by_anyone_after_return() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember("윤서진"));
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(loan(bookId, registerMember("정하윤")))
                .andExpect(status().isCreated());
    }

