    void listing_reservations_for_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(get("/books/{bookId}/reservations", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    String reserveAndGetId(String bookId, String memberId, int expectedPosition) throws Exception {
        String reserved = mockMvc.perform(reserve(bookId, memberId))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(expectedPosition))
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(reserved).get("reservationId").asText();
    }

    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder reserve(String bookId, String memberId)
            throws Exception {
        return post("/books/{bookId}/reservations", bookId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(new ReservationBody(memberId)));
    }

    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder loan(String bookId, String memberId)
